/* Original dependency-free isometric motion illustration. */
(()=>{
  'use strict';
  const canvas=document.getElementById('road-scene'),ctx=canvas.getContext('2d');
  if(!ctx)return;
  let width=600,height=530,scale=20,time=12,angle=-.55,targetAngle=-.55,pointer=0,active=true,motion=!document.body.classList.contains('motion-off'),last=0,frame=0;
  const project=(x,y,z)=>{const c=Math.cos(angle),s=Math.sin(angle),px=x*c-z*s,pz=x*s+z*c;return [width*.5+px*scale,height*.53+pz*scale*.55-y*scale];};
  function poly(points,fill,stroke){ctx.beginPath();points.forEach((p,i)=>{const q=project(...p);i?ctx.lineTo(...q):ctx.moveTo(...q);});ctx.closePath();if(fill){ctx.fillStyle=fill;ctx.fill();}if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=.6;ctx.stroke();}}
  function line(points,color,lineWidth=1){ctx.beginPath();points.forEach((p,i)=>{const q=project(...p);i?ctx.lineTo(...q):ctx.moveTo(...q);});ctx.strokeStyle=color;ctx.lineWidth=lineWidth;ctx.stroke();}
  function world(lx,ly,lz,x,z,rot){return[x+lx*Math.cos(rot)-lz*Math.sin(rot),ly,z+lx*Math.sin(rot)+lz*Math.cos(rot)];}
  function box(x,y,z,w,h,d,colors,rot=0){const vertices=[[-w/2,y,-d/2],[w/2,y,-d/2],[w/2,y,d/2],[-w/2,y,d/2],[-w/2,y+h,-d/2],[w/2,y+h,-d/2],[w/2,y+h,d/2],[-w/2,y+h,d/2]].map(p=>world(...p,x,z,rot));const faces=[[0,1,5,4,colors[1]],[1,2,6,5,colors[2]],[2,3,7,6,colors[2]],[3,0,4,7,colors[1]],[4,5,6,7,colors[0]]];faces.sort((a,b)=>{const depth=f=>f.slice(0,4).reduce((v,i)=>v+vertices[i][0]*Math.sin(angle)+vertices[i][2]*Math.cos(angle),0);return depth(a)-depth(b);});faces.forEach(f=>poly(f.slice(0,4).map(i=>vertices[i]),f[4]));}
  const road=t=>({x:-12+24*t,z:3.6*Math.sin(t*Math.PI*2-.7)});
  const roadAngle=t=>Math.atan2(3.6*Math.PI*2*Math.cos(t*Math.PI*2-.7),24);
  const offset=(t,n)=>{const p=road(t),a=roadAngle(t);return[p.x-Math.sin(a)*n,0,p.z+Math.cos(a)*n];};
  function roadStrip(from,to,n1,n2,y,fill){const pts=[];for(let i=0;i<=120;i++){const p=offset(from+(to-from)*i/120,n1);p[1]=y;pts.push(p);}for(let i=120;i>=0;i--){const p=offset(from+(to-from)*i/120,n2);p[1]=y;pts.push(p);}poly(pts,fill);}
  function tree(x,z,size){const p=project(x,0,z);ctx.fillStyle='#6e7c5320';ctx.beginPath();ctx.ellipse(p[0]+8,p[1]+2,size*scale*.9,size*scale*.35,0,0,Math.PI*2);ctx.fill();box(x,0,z,.12,size*.8,.12,['#899474','#8a9476','#697358']);const top=[x,size*2.1,z],corners=[[x-size*.65,size*.3,z-size*.65],[x+size*.65,size*.3,z-size*.65],[x+size*.65,size*.3,z+size*.65],[x-size*.65,size*.3,z+size*.65]];poly([corners[0],corners[1],top],'#a5b193');poly([corners[1],corners[2],top],'#7f926f');poly([corners[2],corners[3],top],'#879a76');poly([corners[3],corners[0],top],'#b5bea1');}
  function wheel(x,y,z,rot){const vertices=[];for(let i=0;i<=14;i++){const a=i/14*Math.PI*2;vertices.push(world(Math.cos(a)*.23,y+Math.sin(a)*.23,0,x,z,rot));}poly(vertices,'#252f2b');const inner=[];for(let i=0;i<=14;i++){const a=i/14*Math.PI*2;inner.push(world(Math.cos(a)*.115,y+Math.sin(a)*.115,0,x,z,rot));}poly(inner,'#9ba59a');}
  function truck(t,lane,reverse=false){const p=offset(t,lane),rot=roadAngle(t)+(reverse?Math.PI:0);const part=(lx,y,lz,w,h,d,col)=>{const p2=world(lx,y,lz,p[0],p[2],rot);box(p2[0],y,p2[2],w,h,d,col,rot);};const col=['#f1eee0','#d6d5c6','#b7c0af'],orange=['#f38c5c','#d96336','#e77644'];const shadow=[[-2.4,.05,-.65],[1.5,.05,-.65],[1.5,.05,.85],[-2.4,.05,.85]].map(v=>world(...v,p[0]+.15,p[2]+.12,rot));poly(shadow,'#172e2c30');part(-.55,.23,0,3.6,.15,1,['#4f5a50','#455148','#36453e']);part(-1,.57,0,2.65,1.02,.94,col);part(-1,1.6,0,2.65,.035,.96,['#fffaf0','#f1eee0','#e0e0d2']);part(-1,.65,.478,2.53,.12,.018,['#db744d','#db744d','#db744d']);part(.78,.49,0,.72,1.03,.95,orange);part(1.34,.46,0,.48,.55,.85,orange);part(1.62,.4,0,.1,.18,.92,['#c8cdbf','#929e94','#9eaa9d']);part(.86,1.19,.481,.45,.28,.015,['#344e47','#344e47','#344e47']);part(1.15,1.14,0,.012,.32,.72,['#344e47','#344e47','#344e47']);part(.58,1.52,0,.49,.12,.88,orange);[-1.85,-1.35,.12,1.16].forEach(lx=>[-.54,.54].forEach(lz=>{const q=world(lx,.29,lz,p[0],p[2],rot);wheel(q[0],.29,q[2],rot);}));part(1.68,.66,-.31,.02,.08,.12,['#fff6c1','#fff6c1','#fff6c1']);part(1.68,.66,.31,.02,.08,.12,['#fff6c1','#fff6c1','#fff6c1']);}
  function render(){ctx.clearRect(0,0,width,height);const base=[];for(let i=0;i<=100;i++){const a=i/100*Math.PI*2;base.push([Math.cos(a)*13,-.3,Math.sin(a)*6.9]);}poly(base,'#d7dccb');const top=base.map(p=>[p[0],-.06,p[2]]);poly(top,'#e5e7d9');for(let r=0;r<5;r++){const contour=[];for(let i=0;i<=100;i++){const a=i/100*Math.PI*2;contour.push([Math.cos(a)*(10-r*.8),-.04,Math.sin(a)*(5-r*.55)]);}line(contour,'#a9b49a30',.7);}roadStrip(0,1,-1.65,1.65,0,'#a8af9b');roadStrip(0,1,-1.48,1.48,.02,'#fbf6e8');roadStrip(0,1,-1.35,1.35,.03,'#535f56');roadStrip(0,1,-.04,.04,.04,'#e5ad69');for(let i=0;i<32;i++){roadStrip(i/32,(i+.46)/32,-1.23,-1.18,.045,'#c7cbbb');roadStrip(i/32,(i+.46)/32,1.18,1.23,.045,'#c7cbbb');}
    const props=[{x:-8,z:2.4,size:.65},{x:-7,z:3.3,size:.8},{x:-5.8,z:4.1,size:.55},{x:6.2,z:-3.6,size:.8},{x:7.5,z:-3.1,size:.6},{x:8.9,z:-2.8,size:.9},{x:-.3,z:-4.6,size:.5}];const sceneObjects=props.map(p=>({depth:p.x*Math.sin(angle)+p.z*Math.cos(angle),draw:()=>tree(p.x,p.z,p.size)}));[{t:((time*.018+.23)%1),lane:.69},{t:1-((time*.015+.42)%1),lane:-.69,reverse:true}].forEach(p=>{const pos=road(p.t);sceneObjects.push({depth:pos.x*Math.sin(angle)+pos.z*Math.cos(angle),draw:()=>truck(p.t,p.lane,p.reverse)});});sceneObjects.sort((a,b)=>a.depth-b.depth).forEach(p=>p.draw());
    [-.01,.99].forEach(t=>{const p=offset(t,2);box(p[0],0,p[2],.08,.85,.08,['#899c7e','#71866b','#5b7256']);box(p[0],.75,p[2],.5,.23,.06,['#d5dec4','#9dae94','#9dae94']);});
  }
  function resize(){const rect=canvas.getBoundingClientRect();width=rect.width;height=rect.height;const dpr=Math.min(devicePixelRatio||1,2);canvas.width=width*dpr;canvas.height=height*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);scale=Math.min(width/29,height/17);render();}
  function loop(now){const dt=Math.min((now-last)/1000,.05);last=now;if(active&&!document.hidden){if(motion)time+=dt;angle+=(targetAngle+pointer-angle)*.035;render();}if(active&&motion)frame=requestAnimationFrame(loop);}
  function start(){cancelAnimationFrame(frame);last=performance.now();if(active&&motion)frame=requestAnimationFrame(loop);else render();}
  new ResizeObserver(resize).observe(canvas);new IntersectionObserver(([entry])=>{active=entry.isIntersecting;start();},{rootMargin:'80px'}).observe(canvas);
  document.addEventListener('visibilitychange',()=>{if(!document.hidden)start();});document.addEventListener('motionchange',e=>{motion=e.detail;start();});
  document.getElementById('hero-art').addEventListener('pointermove',e=>{if(e.pointerType==='mouse'&&motion){const r=canvas.getBoundingClientRect();pointer=(e.clientX-r.left-r.width/2)/r.width*.12;}},{passive:true});document.getElementById('hero-art').addEventListener('pointerleave',()=>pointer=0);
  document.getElementById('scene-angle').addEventListener('click',()=>{targetAngle=targetAngle<-.7?-.55:-.95;if(!motion){angle=targetAngle;render();}});
  resize();start();
})();
